import os
import base64
import mimetypes
from typing import Any, Dict, Optional

import requests


class OpenAIImageSafetyChecker:
    """
    Checks an image for unsafe or policy-sensitive visual content using OpenAI's hosted API.
    Requires the environment variable OPENAI_API_KEY.
    """

    def __init__(self, api_key: Optional[str] = None, model: str = "gpt-4.1-mini") -> None:
        self.api_key = api_key or os.getenv("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("Missing OpenAI API key. Set OPENAI_API_KEY or pass api_key.")
        self.model = model
        self.base_url = "https://api.openai.com/v1/responses"

    @staticmethod
    def _image_to_data_url(image_path: str) -> str:
        mime_type, _ = mimetypes.guess_type(image_path)
        if not mime_type:
            mime_type = "image/jpeg"
        with open(image_path, "rb") as f:
            encoded = base64.b64encode(f.read()).decode("utf-8")
        return f"data:{mime_type};base64,{encoded}"

    def check_image(self, image_path: str) -> Dict[str, Any]:
        data_url = self._image_to_data_url(image_path)

        prompt = (
            "Analyze the image for unsafe or policy-sensitive visual content. "
            "Focus on: nudity/sexual content, violence/gore, self-harm, hate symbols, "
            "illegal goods, weapons, drugs, exploitation, and other concerning content. "
            "Return a compact JSON object with keys: "
            "safe (boolean), risk_level (one of: low, medium, high), "
            "categories (array of strings), and summary (string)."
        )

        payload = {
            "model": self.model,
            "input": [
                {
                    "role": "system",
                    "content": [{"type": "input_text", "text": "You are a visual safety classifier."}],
                },
                {
                    "role": "user",
                    "content": [
                        {"type": "input_text", "text": prompt},
                        {"type": "input_image", "image_url": data_url},
                    ],
                },
            ],
        }

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }

        response = requests.post(self.base_url, headers=headers, json=payload, timeout=60)
        response.raise_for_status()
        data = response.json()

        text_output = ""
        for item in data.get("output", []):
            for content in item.get("content", []):
                if content.get("type") in ("output_text", "text"):
                    text_output += content.get("text", "")

        return {
            "provider": "openai",
            "model": self.model,
            "raw_response": data,
            "analysis_text": text_output.strip(),
        }


def check_image_for_unsafe_content(image_path: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    checker = OpenAIImageSafetyChecker(api_key=api_key)
    return checker.check_image(image_path)
